const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const TOKEN_KEY='tdkt_v153_static_session';
function getToken(){return sessionStorage.getItem(TOKEN_KEY)||''}
function setToken(t){if(t)sessionStorage.setItem(TOKEN_KEY,t);else sessionStorage.removeItem(TOKEN_KEY)}
async function api(url,opt={}){try{return await window.TDKT_LOCAL.api(url,opt)}catch(e){if(e?.status===401||e?.message==='unauthorized'){location='login.html';throw new Error('unauthorized')}throw e}}
async function protectedFile(path,openInNewTab=false){return window.TDKT_LOCAL.protectedFile(path,openInNewTab)}
function pageHref(href){if(!href||!href.startsWith('/'))return href;if(href.startsWith('/api/'))return href;if(href.startsWith('/static/mau_nhap_du_lieu.xlsx'))return 'mau_nhap_du_lieu.xlsx';const [p,q='']=href.split('?');const map={'/':'index.html','/index.html':'index.html','/personnel':'personnel.html','/personnel.html':'personnel.html','/annual':'annual.html','/annual.html':'annual.html','/standards':'standards.html','/standards.html':'standards.html','/eligibility':'standards.html','/roadmap':'standards.html','/simulations':'standards.html','/legal':'legal.html','/legal.html':'legal.html','/reports':'reports.html','/reports.html':'reports.html','/admin':'admin.html','/admin.html':'admin.html','/login':'login.html','/login.html':'login.html','/change-password':'change-password.html','/change-password.html':'change-password.html'};return (map[p]||p.replace(/^\//,''))+(q?'?'+q:'')}
function rewriteLinks(root=document){root.querySelectorAll?.('a[href]').forEach(a=>{const raw=a.getAttribute('href');if(!raw)return;if(raw.startsWith('/api/')){if(a.dataset.apiBound)return;a.dataset.apiBound='1';a.addEventListener('click',e=>{e.preventDefault();protectedFile(raw,raw.includes('/legal-documents/')||raw.endsWith('.pdf')).catch(err=>alert(err.message))})}else if(raw.startsWith('/'))a.setAttribute('href',pageHref(raw))})}
const mo=new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes)if(n.nodeType===1)rewriteLinks(n)});mo.observe(document.documentElement,{childList:true,subtree:true});
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function badge(status){if(['Có thể xem xét','Đã đáp ứng','Đã kiểm tra'].includes(status))return `<span class="badge green">${esc(status)}</span>`;if(['Chưa đủ điều kiện','Chưa đáp ứng','Hết hiệu lực'].includes(status))return `<span class="badge red">${esc(status)}</span>`;if(['Cần kiểm tra thêm','Cần kiểm tra','Chờ kiểm tra'].includes(status))return `<span class="badge yellow">${esc(status)}</span>`;return `<span class="badge gray">${esc(status)}</span>`}
function legalLocation(r){return [r.article?`Điều ${esc(r.article)}`:'',r.clause?`khoản ${esc(r.clause)}`:'',r.point?`điểm ${esc(r.point)}`:''].filter(Boolean).join(', ')}
function renderLegalRefs(refs=[]){if(!refs.length)return '<div class="muted">Chưa cấu hình chuỗi căn cứ pháp lý.</div>';return `<div class="legal-chain">${refs.map((r,i)=>`<div class="legal-ref"><div class="legal-ref-index">${i+1}</div><div class="legal-ref-body"><div class="legal-ref-head"><b>${esc(r.document||'Chưa xác định')}</b>${legalLocation(r)?`<span>${legalLocation(r)}</span>`:''}${r.verification_status?badge(r.verification_status):''}</div>${r.amendment?`<div class="amendment-tag">${esc(r.amendment)}</div>`:''}${r.quote?`<div class="quote compact">${esc(r.quote)}</div>`:''}${r.note?`<div class="muted">${esc(r.note)}</div>`:''}<div class="legal-actions">${r.effective_date?`<span>Hiệu lực: ${esc(r.effective_date)}</span>`:''}${r.source_url?`<a target="_blank" href="${r.source_url}">Mở văn bản nguồn ↗</a>`:''}</div></div></div>`).join('')}</div>`}
function modal(title,body){let m=$('#modalGlobal');if(!m){m=document.createElement('div');m.id='modalGlobal';m.className='modal';m.innerHTML='<div class="modal-card"><div class="section-title"><h3></h3><button class="btn" data-close>Đóng</button></div><div class="modal-body"></div></div>';document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-close]'))m.classList.remove('show')})} $('h3',m).textContent=title;$('.modal-body',m).innerHTML=body;m.classList.add('show');return m}
$('#menuBtn')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$$('.sidebar a').forEach(a=>{if(a.dataset.nav===window.APP_PAGE)a.classList.add('active')});

async function loadDashboard(){const d=await api('/api/dashboard');const maxU=Math.max(1,...d.unit_counts.map(x=>x.count));const maxR=Math.max(1,...d.rating_counts.map(x=>x.count));$('#content').innerHTML=`<div class="grid cards">${[['👥','Tổng số cán bộ',d.total_personnel,'/personnel'],['📝','Hồ sơ cập nhật '+d.year,d.updated_this_year,'/annual'],['✓','Có thể xem xét',d.can_consider,'/standards?mode=roadmap'],['!','Chưa đủ điều kiện',d.not_enough,'/standards?mode=roadmap'],['?','Cần kiểm tra',d.need_review,'/standards?mode=roadmap'],['⚖','Văn bản đang hiệu lực',d.effective_docs,'/legal']].map(x=>`<a class="card metric" href="${x[3]}" style="text-decoration:none;color:inherit"><div class="icon">${x[0]}</div><div class="k">${x[2]}</div><div class="label">${x[1]}</div></a>`).join('')}</div><div class="grid" style="grid-template-columns:repeat(2,minmax(0,1fr));margin-top:18px"><div class="card"><h3>Cán bộ theo đơn vị</h3>${d.unit_counts.length?d.unit_counts.map(x=>`<div style="margin:10px 0"><div class="toolbar" style="justify-content:space-between"><span>${esc(x.name)}</span><b>${x.count}</b></div><div style="height:9px;background:#edf1f5;border-radius:99px;overflow:hidden"><div style="height:100%;width:${Math.max(4,Math.round(x.count/maxU*100))}%;background:var(--blue)"></div></div></div>`).join(''):'<div class="empty">Chưa có dữ liệu</div>'}</div><div class="card"><h3>Xếp loại năm ${d.year}</h3>${d.rating_counts.length?d.rating_counts.map(x=>`<div style="margin:10px 0"><div class="toolbar" style="justify-content:space-between"><span>${esc(x.name)}</span><b>${x.count}</b></div><div style="height:9px;background:#edf1f5;border-radius:99px;overflow:hidden"><div style="height:100%;width:${Math.max(4,Math.round(x.count/maxR*100))}%;background:var(--green)"></div></div></div>`).join(''):'<div class="empty">Chưa có dữ liệu</div>'}</div></div><div class="section-title"><h2>Nguyên tắc sử dụng kết quả</h2></div><div class="card"><div class="alert info"><b>Hệ thống chỉ hỗ trợ rà soát.</b> Không sử dụng kết luận “đương nhiên được khen thưởng”. Mọi kết quả phải truy nguyên được đến quy tắc “Đã kiểm tra” và văn bản chuyên ngành tương ứng.</div></div>`}
async function getDepts(){return api('/api/departments')}
async function getPeople(q=''){return api('/api/personnel?q='+encodeURIComponent(q))}
async function loadPersonnel(){let rows=await getPeople();$('#content').innerHTML=`<div class="section-title"><div><h2>Hồ sơ cá nhân</h2><div class="muted">Quản lý thông tin nền dùng để theo dõi thành tích và đối chiếu điều kiện khen thưởng.</div></div><div class="toolbar"><input id="searchP" class="input search" placeholder="Tìm theo họ tên hoặc mã hồ sơ">${APP_USER.role!=='viewer'?'<button id="addP" class="btn primary">+ Thêm hồ sơ</button>':''}</div></div><div id="pTable"></div>`;renderP(rows);$('#searchP').oninput=async e=>renderP(await getPeople(e.target.value));if($('#addP'))$('#addP').onclick=addPersonnel}
function renderP(rows){$('#pTable').innerHTML=`<div class="table-wrap"><table class="person-table"><thead><tr><th>Mã hồ sơ</th><th>Họ và tên</th><th>Năm sinh</th><th>Chức vụ</th><th>Phòng và tương đương</th><th>Đơn vị</th><th>Trạng thái</th><th>Chấp hành</th><th>Thao tác</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${esc(x.full_name)}</td><td>${esc(x.birth_year||'—')}</td><td>${esc(x.position||'—')}</td><td>${esc(x.division||'—')}</td><td>${esc(x.department_name||'—')}</td><td>${esc(x.status)}</td><td>${x.law_compliance===true?badge('Đã đáp ứng'):x.law_compliance===false?badge('Chưa đáp ứng'):badge('Cần kiểm tra')}</td><td><div class="toolbar"><button class="btn compact" onclick="showTimeline(${x.id},'${esc(x.full_name)}')">Thành tích theo năm</button>${APP_USER.role!=='viewer'?`<button class="btn compact danger" onclick="deletePersonnel(${x.id})">Xóa hồ sơ</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`}
async function addPersonnel(){let currentYear=new Date().getFullYear();let m=modal('Thêm hồ sơ cá nhân',`<form id="pForm" class="form-grid personnel-form"><label>Mã hồ sơ <span class="req">*</span><input name="code" required placeholder="Ví dụ: HS0001"></label><label>Họ và tên <span class="req">*</span><input name="full_name" required placeholder="Nhập đầy đủ họ và tên"></label><label>Năm sinh<input name="birth_year" type="number" min="1900" max="${currentYear}" placeholder="Ví dụ: 1985"></label><label>Chức vụ<input name="position" placeholder="Nhập chức vụ"></label><label>Phòng và tương đương<input name="division" placeholder="Nhập phòng/ban/bộ phận"></label><label>Đơn vị <span class="req">*</span><input name="department_name" required autocomplete="off" placeholder="Nhập tên đơn vị"><small class="field-help">Để trống ban đầu và nhập đúng tên đơn vị của hồ sơ.</small></label><label>Ngày bắt đầu công tác<input name="start_date" type="date"></label><label>Trạng thái<select name="status"><option>Đang công tác</option><option>Chuyển công tác</option><option>Nghỉ hưu</option></select></label><label>Gương mẫu chấp hành<select name="law_compliance"><option value="">Chưa xác nhận</option><option value="true">Đã xác nhận đáp ứng</option><option value="false">Không đáp ứng</option></select></label><label class="full">Ghi chú<textarea name="notes" rows="3" placeholder="Thông tin cần lưu ý khác (nếu có)"></textarea></label><div class="full form-actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu hồ sơ</button></div></form>`);$('#pForm',m).onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target);if(!fd.get('birth_year'))fd.delete('birth_year');try{await api('/api/personnel',{method:'POST',body:fd});m.classList.remove('show');loadPersonnel()}catch(err){alert(err.message)}}}
async function showTimeline(id,name){let rows=await api(`/api/personnel/${id}/timeline`);modal('Dòng thời gian - '+name,rows.length?`<div class="timeline">${rows.map(x=>`<div class="timeline-item"><div class="year-dot">${x.year}</div><div class="card"><b>${esc(x.rating||'Chưa có xếp loại')}</b>${x.locked?' '+badge('Đã kiểm tra'):''}<p>Danh hiệu: ${x.titles.map(t=>esc(t.name)).join('; ')||'—'}</p><p>Khen thưởng: ${x.rewards.map(t=>esc(t.name)).join('; ')||'—'}</p><p>Sáng kiến/nhiệm vụ: ${x.initiatives.map(t=>esc(t.name)+' ('+esc(t.scope||'')+')').join('; ')||'—'}</p></div></div>`).join('')}</div>`:'<div class="empty">Chưa có dữ liệu theo năm.</div>')}
async function deletePersonnel(id){try{const people=await getPeople();const p=people.find(x=>x.id===id);if(!p){alert('Không tìm thấy hồ sơ cá nhân.');return}const years=await api(`/api/personnel/${id}/timeline`);const extra=years.length?`\n\nHồ sơ này đang có dữ liệu thành tích của ${years.length} năm. Khi xóa, toàn bộ xếp loại, danh hiệu, khen thưởng và sáng kiến gắn với hồ sơ cũng sẽ bị xóa khỏi trình duyệt này.`:'\n\nHồ sơ chưa có dữ liệu thành tích theo năm.';if(!confirm(`Bạn có chắc muốn xóa hồ sơ:\n${p.code} - ${p.full_name}?${extra}\n\nThao tác này không thể hoàn tác nếu chưa có bản sao lưu.`))return;await api(`/api/personnel/${id}/delete`,{method:'POST'});alert(`Đã xóa hồ sơ ${p.full_name}.`);await loadPersonnel()}catch(err){alert(err.message||'Không thể xóa hồ sơ')}}

async function loadAnnual(){
  let people=await getPeople();
  let opts=await api('/api/annual/options');
  let yr=new Date().getFullYear();
  const canWrite=APP_USER.role!=='viewer';
  let activeAnnualContext=null;
  let annualRows=[];

  const peopleOpts=people.map(p=>`<option value="${p.id}">${esc(p.code)} - ${esc(p.full_name)}</option>`).join('');
  const titleOpts=opts.titles.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('');
  const rewardOpts=opts.rewards.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('');
  const rewardCategoryOpts=(opts.reward_categories||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');

  $('#content').innerHTML=`<div class="annual-banner"><div class="annual-banner-symbol"><div class="vn-flag large"><span>★</span></div><div class="calendar-mark"><b>12</b><span>THÁNG</span></div></div><div class="annual-banner-copy"><span class="eyebrow">THEO DÕI THÀNH TÍCH HẰNG NĂM</span><h2>Mỗi năm một hồ sơ rõ ràng, đủ căn cứ để tính các chuỗi thành tích</h2><p>Quản lý xếp loại, danh hiệu thi đua, hình thức khen thưởng và sáng kiến theo cùng một năm. Dữ liệu này được dùng trực tiếp khi đối chiếu điều kiện 02 năm, 03 năm liên tục và các mốc khen thưởng tiền đề.</p></div><div class="annual-year-box"><label>Năm theo dõi<input id="overviewYear" type="number" value="${yr}"></label><button id="reloadAnnual" class="btn primary">↻ Cập nhật danh sách</button></div></div>
  <div class="annual-tabs" role="tablist"><button class="annual-tab active" data-annual-tab="overview">① Tổng quan năm</button>${canWrite?'<button class="annual-tab" data-annual-tab="editor">② Cập nhật từng hồ sơ</button><button class="annual-tab" data-annual-tab="import">③ Chuyển dữ liệu</button>':''}</div>
  <section id="annualTabOverview" class="annual-tab-section active"><div id="annualMetrics" class="annual-metrics"></div><div class="card annual-overview-card"><div class="overview-head"><div><h3>Danh sách theo dõi năm <span id="overviewTitleYear">${yr}</span></h3><p>Ưu tiên xử lý các hồ sơ còn thiếu dữ liệu nền; danh hiệu, khen thưởng và sáng kiến được hiển thị riêng, không coi việc “không phát sinh” là lỗi.</p></div><div class="toolbar"><input id="annualSearch" class="input" placeholder="Tìm mã hồ sơ hoặc họ tên"><select id="annualStatusFilter"><option value="all">Tất cả trạng thái</option><option value="missing">Còn thiếu dữ liệu nền</option><option value="ready">Đủ dữ liệu, chưa xác nhận</option><option value="confirmed">Đã xác nhận cập nhật</option><option value="locked">Đã chốt</option></select>${canWrite?'<button id="lockAll" class="btn success">✓ Chốt dữ liệu năm</button>':''}${APP_USER.role==='admin'?'<button id="unlockAll" class="btn">Mở lại năm</button>':''}</div></div><div id="annualOverview"></div></div></section>
  ${canWrite?`<section id="annualTabEditor" class="annual-tab-section"><div class="card annual-editor"><div class="editor-head"><div><span class="eyebrow">CẬP NHẬT CHI TIẾT</span><h3>Hồ sơ thành tích của một cán bộ</h3><p>Chọn cán bộ và năm rồi bấm <b>Mở hồ sơ năm</b>. Trong khi cập nhật, cán bộ và năm được cố định; muốn chuyển sang hồ sơ khác hãy dùng nút <b>Đổi hồ sơ/năm</b> ở cuối.</p></div><div class="toolbar annual-pick"><label>Cán bộ<select id="annualPerson">${peopleOpts}</select></label><label>Năm<input id="annualYear" type="number" value="${yr}"></label><button id="loadAnnualDetail" class="btn primary">Mở hồ sơ năm</button></div></div><div id="annualDetail" class="annual-detail"><div class="empty">Chọn cán bộ và bấm <b>Mở hồ sơ năm</b>.</div></div></div></section>
  <section id="annualTabImport" class="annual-tab-section"><div class="card import-card"><div><span class="eyebrow">CHUYỂN / SAO LƯU DỮ LIỆU</span><h3>Nhập dữ liệu hàng loạt</h3><p class="muted">Bản GitHub Pages tĩnh lưu dữ liệu trên trình duyệt. Có thể dùng tệp mẫu để chuẩn bị dữ liệu; sao lưu/khôi phục đầy đủ thực hiện tại mục Quản trị.</p></div><form id="annualImport" class="import-box"><input type="file" name="file" accept=".xlsx" required><div class="toolbar"><button class="btn primary">Nhập Excel</button><a class="btn" href="/static/mau_nhap_du_lieu.xlsx">Tải tệp mẫu</a></div></form><div id="importResult" class="muted"></div></div></section>`:'<div class="alert info">Tài khoản Người xem chỉ được tra cứu dữ liệu, không được cập nhật/chốt.</div>'}
  <div class="annual-note"><b>Nguyên tắc dữ liệu:</b> xếp loại là dữ liệu nền; danh hiệu, hình thức khen thưởng và sáng kiến chỉ ghi khi thực tế phát sinh. <b>Xác nhận cập nhật</b> là bước hoàn tất nhập liệu của một hồ sơ/năm; <b>Chốt năm</b> là bước khóa dữ liệu theo thẩm quyền.</div>`;

  function setAnnualTab(tab){
    $$('.annual-tab').forEach(b=>b.classList.toggle('active',b.dataset.annualTab===tab));
    $$('.annual-tab-section').forEach(s=>s.classList.remove('active'));
    $(`#annualTab${tab[0].toUpperCase()+tab.slice(1)}`)?.classList.add('active');
  }
  function annualState(x){
    if(x.locked)return 'locked';
    if(x.issues?.length)return 'missing';
    if(x.confirmed)return 'confirmed';
    return 'ready';
  }
  function renderMetrics(rows){
    let updated=rows.filter(x=>x.rating||x.titles?.length||x.rewards?.length||x.initiatives?.length).length;
    let locked=rows.filter(x=>x.locked).length;
    let confirmed=rows.filter(x=>x.confirmed&&!x.locked).length;
    let missing=rows.filter(x=>x.issues?.length).length;
    let cstd=rows.filter(x=>(x.titles||[]).some(v=>normText(v).includes(normText('Chiến sĩ thi đua cơ sở')))).length;
    $('#annualMetrics').innerHTML=`${[[rows.length,'Tổng hồ sơ','👥','blue'],[updated,'Đã có dữ liệu năm','📝','blue'],[missing,'Còn thiếu dữ liệu nền','!','amber'],[confirmed,'Đã xác nhận cập nhật','✓','green'],[locked,'Đã chốt','🔒','green'],[cstd,'Có CSTĐ cơ sở','🏅','green']].map(x=>`<div class="annual-metric ${x[3]}"><div class="metric-icon">${x[2]}</div><div><b>${x[0]}</b><span>${x[1]}</span></div></div>`).join('')}`;
  }
  function renderOverviewRows(){
    let q=normText($('#annualSearch')?.value||''),sf=$('#annualStatusFilter')?.value||'all';
    let rows=annualRows.filter(x=>(!q||normText(`${x.code} ${x.full_name}`).includes(q))&&(sf==='all'||annualState(x)===sf));
    $('#annualOverview').innerHTML=rows.length?`<div class="table-wrap"><table class="annual-table modern"><thead><tr><th>Hồ sơ</th><th>Xếp loại</th><th>Danh hiệu thi đua</th><th>Khen thưởng</th><th>Sáng kiến / nhiệm vụ</th><th>Tình trạng dữ liệu</th>${canWrite?'<th></th>':''}</tr></thead><tbody>${rows.map(x=>`<tr><td><div class="person-cell"><b>${esc(x.full_name)}</b><span>${esc(x.code)}</span></div></td><td>${x.rating?`<span class="rating-text">${esc(x.rating)}</span>`:'<span class="empty-value">Chưa cập nhật</span>'}</td><td>${x.titles?.length?x.titles.map(v=>`<span class="mini-tag blue">${esc(v)}</span>`).join(' '):'<span class="empty-value">Không ghi nhận</span>'}</td><td>${x.rewards?.length?x.rewards.map(v=>`<span class="mini-tag green">${esc(v)}</span>`).join(' '):'<span class="empty-value">Không ghi nhận</span>'}</td><td>${x.initiatives?.length?x.initiatives.map(v=>`<span class="mini-tag">${esc(v)}</span>`).join(' '):'<span class="empty-value">Không ghi nhận</span>'}</td><td><div class="data-status ${annualState(x)}">${x.locked?'<b>🔒 Đã chốt</b><span>Dữ liệu năm đã khóa</span>':x.issues.length?`<b>! Cần bổ sung</b><span>${esc(x.issues.join('; '))}</span>`:x.confirmed?'<b>✓ Đã xác nhận cập nhật</b><span>Đã hoàn tất bước nhập liệu</span>':'<b>○ Đủ dữ liệu nền</b><span>Chưa bấm xác nhận hoàn tất</span>'}</div></td>${canWrite?`<td><button class="btn compact annual-edit-row" data-pid="${x.personnel_id}">Cập nhật</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty big"><b>Không có hồ sơ phù hợp bộ lọc.</b><div>Thử đổi trạng thái hoặc từ khóa tìm kiếm.</div></div>';
    $$('.annual-edit-row').forEach(b=>b.onclick=async()=>{
      if(!releaseAnnualContext(true))return;
      $('#annualPerson').value=b.dataset.pid;
      $('#annualYear').value=$('#overviewYear').value;
      setAnnualTab('editor');
      await openAnnualDetail();
      window.scrollTo({top:0,behavior:'smooth'});
    });
  }
  async function overview(){
    let year=$('#overviewYear').value;
    annualRows=await api('/api/annual?year='+year);
    $('#overviewTitleYear').textContent=year;
    renderMetrics(annualRows);
    renderOverviewRows();
  }
  function lockAnnualContextControls(locked){
    if($('#annualPerson'))$('#annualPerson').disabled=locked;
    if($('#annualYear'))$('#annualYear').disabled=locked;
    if($('#loadAnnualDetail')){$('#loadAnnualDetail').disabled=locked;$('#loadAnnualDetail').textContent=locked?'Đang mở hồ sơ':'Mở hồ sơ năm';}
  }
  function releaseAnnualContext(checkDirty=true){
    if(!activeAnnualContext){lockAnnualContextControls(false);return true;}
    if(checkDirty&&$('#annualDetail')?.dataset.dirty==='1'&&!confirm('Có thông tin đang nhập nhưng chưa bấm Lưu/Thêm. Bạn vẫn muốn đổi hồ sơ hoặc năm?'))return false;
    activeAnnualContext=null;
    lockAnnualContextControls(false);
    if($('#annualDetail')){$('#annualDetail').dataset.dirty='0';$('#annualDetail').innerHTML='<div class="empty">Chọn cán bộ và bấm <b>Mở hồ sơ năm</b>.</div>';}
    return true;
  }
  async function openAnnualDetail(){
    let pid=$('#annualPerson').value,year=$('#annualYear').value;
    if(!pid||!year)return;
    activeAnnualContext={pid:String(pid),year:String(year)};
    lockAnnualContextControls(true);
    await renderDetail();
  }
  async function renderDetail(){
    if(!activeAnnualContext)return;
    let pid=activeAnnualContext.pid,year=activeAnnualContext.year;
    let person=people.find(p=>String(p.id)===String(pid));
    let d=await api(`/api/annual/${pid}/${year}/detail`);
    let a=d.performance||{};
    let locked=!!a.locked;
    let confirmed=!!a.confirmed;
    let facts=[['Xếp loại',a.rating?'Đã cập nhật':'Chưa cập nhật',!!a.rating],['Danh hiệu',`${d.titles.length} mục`,d.titles.length>0],['Khen thưởng',`${d.rewards.length} mục`,d.rewards.length>0],['Sáng kiến/NV',`${d.initiatives.length} mục`,d.initiatives.length>0]];
    $('#annualDetail').dataset.dirty='0';
    $('#annualDetail').innerHTML=`<div class="annual-person-head"><div><span class="eyebrow">HỒ SƠ NĂM ${year}</span><h3>${esc(person?.full_name||'')}</h3><div class="muted">${esc(person?.code||'')} · ${esc(person?.position||'Chưa có chức vụ')} · ${esc(person?.department_name||'Chưa có đơn vị')}</div></div><div>${locked?'<span class="badge green">🔒 Đã chốt</span>':confirmed?'<span class="badge green">✓ Đã xác nhận cập nhật</span>':'<span class="badge gray">Đang cập nhật · chưa xác nhận</span>'}</div></div>
    <div class="annual-context-lock"><span>🔒 Năm đang cập nhật được cố định:</span><b>${year}</b><span>·</span><b>${esc(person?.code||'')}</b><span>Muốn chuyển năm/hồ sơ, dùng nút “Đổi hồ sơ/năm” ở cuối.</span></div>
    <div class="annual-fact-strip">${facts.map(x=>`<div class="annual-fact ${x[2]?'has':'none'}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div>
    ${locked?'<div class="alert warning"><b>Năm này đã chốt.</b> Cán bộ nghiệp vụ không được sửa cho đến khi được mở lại theo thẩm quyền.</div>':''}
    ${confirmed&&!locked?`<div class="alert success-soft"><b>Hồ sơ năm ${year} đã được xác nhận cập nhật.</b>${a.confirmed_at?` Thời điểm xác nhận: ${esc(a.confirmed_at.replace('T',' ').slice(0,19))}.`:''} Nếu sửa thêm dữ liệu, trạng thái xác nhận sẽ tự hủy và cần xác nhận lại.</div>`:''}
    <div class="annual-grid">
      <section class="annual-section primary-step"><div class="annual-section-head"><div class="num">1</div><div><h3>Đánh giá, xếp loại</h3><p>Dữ liệu nền dùng để tính các tiêu chuẩn theo số năm hoàn thành nhiệm vụ. Có thể lưu tạm; nút xác nhận cuối trang sẽ lưu lại lần cuối trước khi hoàn tất.</p></div></div><form id="perfForm" class="form-grid"><input type="hidden" name="personnel_id" value="${pid}"><input type="hidden" name="year" value="${year}"><label>Xếp loại<select name="rating"><option></option>${['Hoàn thành xuất sắc nhiệm vụ','Hoàn thành tốt nhiệm vụ','Hoàn thành nhiệm vụ','Không hoàn thành nhiệm vụ'].map(v=>`<option ${a.rating===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Số quyết định<input name="decision_no" value="${esc(a.decision_no||'')}"></label><label>Ngày quyết định<input type="date" name="decision_date" value="${esc(a.decision_date||'')}"></label><label class="full">Ghi chú<textarea name="notes" rows="2">${esc(a.notes||'')}</textarea></label><div class="full"><button class="btn" ${locked&&APP_USER.role!=='admin'?'disabled':''}>Lưu tạm xếp loại</button></div></form></section>
      <section class="annual-section"><div class="annual-section-head"><div class="num">2</div><div><h3>Danh hiệu thi đua</h3><p>Ghi đúng năm được tặng để hệ thống tính các chuỗi 02/03 lần liên tục.</p></div></div><div class="item-list">${d.titles.length?d.titles.map(x=>`<div class="achievement-item"><div><b>${esc(x.name)}</b><small>${esc(x.decision_no||'Chưa có số QĐ')} ${x.decision_date?'· '+esc(x.decision_date):''}</small></div><button class="btn compact danger-outline" data-del="title" data-id="${x.id}">Xóa</button></div>`).join(''):'<div class="empty slim">Năm này chưa ghi nhận danh hiệu thi đua.</div>'}</div><form id="titleForm" class="form-grid"><input type="hidden" name="personnel_id" value="${pid}"><input type="hidden" name="year" value="${year}"><label class="full">Danh hiệu<select name="title_code">${titleOpts}</select></label><label>Số quyết định<input name="decision_no"></label><label>Ngày quyết định<input type="date" name="decision_date"></label><div class="full"><button class="btn primary" ${locked&&APP_USER.role!=='admin'?'disabled':''}>+ Thêm danh hiệu</button></div></form></section>
      <section class="annual-section"><div class="annual-section-head"><div class="num">3</div><div><h3>Hình thức khen thưởng</h3><p>Lưu Bằng khen, Huân chương… và <b>loại hình khen thưởng</b>. Trường này rất quan trọng vì nguyên tắc chu kỳ công trạng không được áp dụng máy móc cho khen đột xuất, phong trào, cống hiến, niên hạn hoặc đối ngoại.</p></div></div><div class="item-list">${d.rewards.length?d.rewards.map(x=>`<div class="achievement-item reward-basis-item"><div><b>${esc(x.name)}</b><small>${esc(x.decision_no||'Chưa có số QĐ')} ${x.decision_date?'· '+esc(x.decision_date):''}</small><small class="${x.reward_category?'':'warn-text'}">Loại hình: ${esc(x.reward_category||'CHƯA PHÂN LOẠI — CẦN XÁC NHẬN')}</small>${x.achievement_from_year||x.achievement_to_year?`<small>Khoảng thành tích dùng để khen: ${esc(x.achievement_from_year||'?')}–${esc(x.achievement_to_year||x.year)}</small>`:''}</div><div class="reward-item-actions">${!x.reward_category?`<button class="btn compact" data-classify-reward="${x.id}">Phân loại</button>`:''}<button class="btn compact danger-outline" data-del="reward" data-id="${x.id}">Xóa</button></div></div>`).join(''):'<div class="empty slim">Năm này chưa ghi nhận hình thức khen thưởng.</div>'}</div><form id="rewardForm" class="form-grid"><input type="hidden" name="personnel_id" value="${pid}"><input type="hidden" name="year" value="${year}"><label class="full">Hình thức khen thưởng<select name="reward_code" required>${rewardOpts}</select></label><label class="full">Loại hình khen thưởng<select name="reward_category" required><option value="">— Chọn đúng loại hình —</option>${rewardCategoryOpts}</select></label><label>Năm bắt đầu khoảng thành tích<input type="number" name="achievement_from_year" min="1900" max="${year}" placeholder="Không bắt buộc"></label><label>Năm kết thúc khoảng thành tích<input type="number" name="achievement_to_year" min="1900" max="${year}" placeholder="Thường là ${year}"></label><label>Số quyết định<input name="decision_no"></label><label>Ngày quyết định<input type="date" name="decision_date"></label><label class="full">Ghi chú / căn cứ<input name="notes"></label><div class="full"><button class="btn primary" ${locked&&APP_USER.role!=='admin'?'disabled':''}>+ Thêm khen thưởng</button></div></form></section>
      <section class="annual-section"><div class="annual-section-head"><div class="num">4</div><div><h3>Sáng kiến / nhiệm vụ KHCN-ĐMST</h3><p>Ghi phạm vi công nhận để đối chiếu đúng cấp cơ sở, Bộ/ban/ngành/tỉnh hoặc toàn quốc.</p></div></div><div class="item-list">${d.initiatives.length?d.initiatives.map(x=>`<div class="achievement-item"><div><b>${esc(x.name)}</b><small>${esc(x.kind||'')} · ${esc(x.scope||'Chưa xác định phạm vi')} ${x.recognition_no?'· '+esc(x.recognition_no):''}</small></div><button class="btn compact danger-outline" data-del="initiative" data-id="${x.id}">Xóa</button></div>`).join(''):'<div class="empty slim">Năm này chưa ghi nhận sáng kiến/nhiệm vụ.</div>'}</div><form id="iniForm" class="form-grid"><input type="hidden" name="personnel_id" value="${pid}"><input type="hidden" name="year" value="${year}"><label class="full">Tên sáng kiến / nhiệm vụ<input name="name" required></label><label>Loại<select name="kind"><option>Sáng kiến</option><option>Nhiệm vụ KHCN-ĐMST</option><option>Đề tài / công trình chuyển tiếp</option></select></label><label>Phạm vi<select name="scope"><option value="">Chưa xác định</option><option>Cơ sở</option><option>Bộ, ban, ngành, tỉnh</option><option>Toàn quốc</option></select></label><label>Số văn bản công nhận<input name="recognition_no"></label><label>Ngày công nhận<input type="date" name="recognition_date"></label><div class="full"><button class="btn primary" ${locked&&APP_USER.role!=='admin'?'disabled':''}>+ Thêm sáng kiến / nhiệm vụ</button></div></form></section>
    </div>
    <div class="annual-confirm-panel ${confirmed?'is-confirmed':''}"><div class="annual-confirm-copy"><span class="eyebrow">BƯỚC CUỐI CÙNG</span><h3>${confirmed?'Đã xác nhận cập nhật hồ sơ năm '+year:'Xác nhận hoàn tất cập nhật hồ sơ năm '+year}</h3><p>${confirmed?'Dữ liệu hiện tại đã được xác nhận. Nếu tiếp tục sửa hoặc thêm thành tích, trạng thái này tự chuyển về “chưa xác nhận”.':'Sau khi đã lưu xếp loại và thêm các thành tích phát sinh, bấm xác nhận để hoàn tất nhập liệu cho đúng cán bộ và đúng năm đang mở.'}</p></div><div class="annual-confirm-actions"><button id="changeAnnualContext" class="btn">↔ Đổi hồ sơ/năm</button><button id="confirmAnnualUpdate" class="btn success" ${locked&&APP_USER.role!=='admin'?'disabled':''}>✓ ${confirmed?'Xác nhận lại':'Xác nhận hoàn tất cập nhật'}</button></div></div>`;

    const detail=$('#annualDetail');
    const setDirty=()=>detail.dataset.dirty='1';
    ['perfForm','titleForm','rewardForm','iniForm'].forEach(id=>{
      let f=$('#'+id);if(!f)return;
      $$('input:not([type="hidden"]),select,textarea',f).forEach(el=>{el.addEventListener('input',setDirty);el.addEventListener('change',setDirty)});
    });
    let pending={title:false,reward:false,initiative:false};
    [['titleForm','title'],['rewardForm','reward'],['iniForm','initiative']].forEach(([id,key])=>{
      let f=$('#'+id);if(!f)return;
      $$('input:not([type="hidden"]),select,textarea',f).forEach(el=>{el.addEventListener('input',()=>pending[key]=true);el.addEventListener('change',()=>pending[key]=true)});
    });

    $('#perfForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/annual',{method:'POST',body:new FormData(e.target)});await renderDetail();await overview()}catch(err){alert(err.message)}};
    $('#titleForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/annual/title',{method:'POST',body:new FormData(e.target)});pending.title=false;await renderDetail();await overview()}catch(err){alert(err.message)}};
    $('#rewardForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/annual/reward',{method:'POST',body:new FormData(e.target)});pending.reward=false;await renderDetail();await overview()}catch(err){alert(err.message)}};
    $('#iniForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/annual/initiative',{method:'POST',body:new FormData(e.target)});pending.initiative=false;await renderDetail();await overview()}catch(err){alert(err.message)}};
    $$('[data-classify-reward]',detail).forEach(b=>b.onclick=async()=>{let cat=prompt('Nhập đúng loại hình khen thưởng:\n- Công trạng\n- Đột xuất\n- Phong trào thi đua\n- Quá trình cống hiến\n- Theo niên hạn\n- Đối ngoại','Công trạng');if(!cat)return;if(!(opts.reward_categories||[]).includes(cat)){alert('Loại hình không hợp lệ. Hãy nhập đúng một giá trị trong danh sách.');return}let f=new FormData();f.append('reward_category',cat);try{await api(`/api/annual/reward/${b.dataset.classifyReward}/classify`,{method:'POST',body:f});await renderDetail();await overview()}catch(err){alert(err.message)}});
    $$('[data-del]',detail).forEach(b=>b.onclick=async()=>{if(!confirm('Xóa dữ liệu thành tích này?'))return;try{await api(`/api/annual/item/${b.dataset.del}/${b.dataset.id}/delete`,{method:'POST'});await renderDetail();await overview()}catch(err){alert(err.message)}});
    $('#changeAnnualContext').onclick=()=>{if(releaseAnnualContext(true))window.scrollTo({top:0,behavior:'smooth'})};
    $('#confirmAnnualUpdate').onclick=async()=>{
      if(pending.title||pending.reward||pending.initiative){
        let names=[];if(pending.title)names.push('Danh hiệu thi đua');if(pending.reward)names.push('Hình thức khen thưởng');if(pending.initiative)names.push('Sáng kiến/nhiệm vụ');
        alert('Bạn đang nhập nhưng chưa bấm Thêm ở mục: '+names.join(', ')+'. Hãy thêm hoặc xóa nội dung đang nhập rồi mới xác nhận.');return;
      }
      if(!confirm(`Xác nhận hoàn tất cập nhật hồ sơ ${person?.code||''} - ${person?.full_name||''}, năm ${year}?`))return;
      try{
        await api('/api/annual',{method:'POST',body:new FormData($('#perfForm'))});
        await api(`/api/annual/${pid}/${year}/confirm-update`,{method:'POST'});
        detail.dataset.dirty='0';
        await renderDetail();
        await overview();
      }catch(err){alert(err.message)}
    };
  }

  $$('.annual-tab').forEach(b=>b.onclick=()=>setAnnualTab(b.dataset.annualTab));
  $('#reloadAnnual').onclick=overview;
  $('#overviewYear').onchange=overview;
  $('#annualSearch').oninput=renderOverviewRows;
  $('#annualStatusFilter').onchange=renderOverviewRows;
  if($('#loadAnnualDetail'))$('#loadAnnualDetail').onclick=openAnnualDetail;
  if($('#annualImport'))$('#annualImport').onsubmit=async e=>{e.preventDefault();try{let r=await api('/api/import/annual',{method:'POST',body:new FormData(e.target)});$('#importResult').innerHTML=`<div class="alert ${r.errors?.length?'warning':'info'}">Đã tạo <b>${r.created}</b>, cập nhật <b>${r.updated}</b>. ${r.errors?.length?'Lỗi/cảnh báo: '+esc(r.errors.join(' | ')):'Không có lỗi.'}</div>`;await overview()}catch(err){$('#importResult').innerHTML=`<div class="alert danger">${esc(err.message)}</div>`}};
  if($('#lockAll'))$('#lockAll').onclick=async()=>{if(!confirm(`Chốt toàn bộ dữ liệu đã có của năm ${$('#overviewYear').value}?`))return;let f=new FormData();f.append('locked','true');let r=await api(`/api/annual/${$('#overviewYear').value}/lock-all`,{method:'POST',body:f});alert(`Đã chốt ${r.count} bản ghi.`);await overview()};
  if($('#unlockAll'))$('#unlockAll').onclick=async()=>{let f=new FormData();f.append('locked','false');let r=await api(`/api/annual/${$('#overviewYear').value}/lock-all`,{method:'POST',body:f});alert(`Đã mở lại ${r.count} bản ghi.`);await overview()};
  await overview();
}
function sourceButtons(sources=[]){return sources.map(s=>s.source_url?`<a class="source-link" target="_blank" href="${s.source_url}">${esc(s.code)} ↗</a>`:`<span class="source-link muted">${esc(s.code)}</span>`).join(' ')}
function normText(s){return String(s||'').toLocaleLowerCase('vi').replace(/[“”"']/g,'').replace(/\s+/g,' ').trim()}
function roadmapStatusText(status){return status==='pass'?'Đã đáp ứng':status==='fail'?'Chưa đáp ứng':'Cần kiểm tra'}
function conditionStats(node,acc={pass:0,fail:0,review:0,missing:[]}){if(!node)return acc;if(node.kind==='group'){let children=node.children||[];if(node.operator==='OR'&&node.status==='pass'){children=children.filter(x=>x.status==='pass')}children.forEach(x=>conditionStats(x,acc));return acc}acc[node.status]=(acc[node.status]||0)+1;if(node.status!=='pass'&&node.missing)acc.missing.push(node.missing);return acc}
function resultOutcome(results=[]){if(results.some(x=>x.outcome==='Có thể xem xét'))return 'Có thể xem xét';if(results.some(x=>x.outcome==='Cần kiểm tra thêm'))return 'Cần kiểm tra thêm';return results.length?'Chưa đủ điều kiện':'Cần kiểm tra thêm'}
function renderConditionTree(node,depth=0){if(!node)return '<div class="empty slim">Chưa có cấu trúc điều kiện để hiển thị.</div>';if(node.kind==='group'){let isOr=node.operator==='OR';return `<div class="condition-group ${isOr?'or-group':'and-group'} status-${node.status}"><div class="condition-group-head"><div><span class="logic-pill ${isOr?'or':'and'}">${isOr?'HOẶC':'VÀ'}</span><b>${esc(node.label)}</b></div>${badge(roadmapStatusText(node.status))}</div>${isOr?`<div class="logic-help">Các nhánh là <b>phương án thay thế</b>; chỉ cần ít nhất một nhánh đạt. Nhánh không cần thiết sẽ được làm mờ khi đã có phương án đạt.</div>`:''}<div class="condition-children">${(node.children||[]).map(ch=>`<div class="${isOr&&node.status==='pass'&&ch.status!=='pass'?'alternative-not-needed':''}">${renderConditionTree(ch,depth+1)}</div>`).join('')}</div></div>`}return `<div class="condition-leaf ${node.status}"><div class="condition-icon">${node.status==='pass'?'✓':node.status==='fail'?'!':'?'}</div><div class="condition-body"><div class="condition-title-row"><b>${esc(node.label)}</b>${badge(roadmapStatusText(node.status))}</div>${node.used_data?`<div class="used-data"><span>Dữ liệu đã đối chiếu</span>${esc(node.used_data)}</div>`:''}${node.missing?`<div class="missing-box"><span>${node.status==='review'?'Cần xác minh':'Còn thiếu / cần bổ sung'}</span>${esc(node.missing)}</div>`:''}${node.explanation?`<div class="muted condition-explain">${esc(node.explanation)}</div>`:''}${node.legal_basis?`<div class="basis">Căn cứ: ${esc(node.legal_basis)}</div>`:''}</div></div>`}
function renderHistory(history=[]){if(!history.length)return '<div class="empty slim">Chưa có thành tích theo năm trước thời điểm xét.</div>';return `<div class="history-strip">${history.map(h=>`<div class="history-year"><div class="history-year-top"><b>${h.year}</b>${h.rating?`<span>${esc(h.rating)}</span>`:'<span>Chưa xếp loại</span>'}</div><div class="history-facts">${(h.titles||[]).map(x=>`<span class="fact title">🏅 ${esc(x)}</span>`).join('')}${(h.rewards||[]).map(x=>`<span class="fact reward">🎖 ${esc(x)}</span>`).join('')}${(h.initiatives||[]).map(x=>`<span class="fact initiative">💡 ${esc(x.name)}${x.scope?` · ${esc(x.scope)}`:''}</span>`).join('')||'<span class="muted mini">Không có sáng kiến/nhiệm vụ ghi nhận</span>'}</div></div>`).join('')}</div>`}
function renderRoadmapAnalysis(data,targetName='',options={}){let results=data.results||[];if(!results.length)return `<div class="empty big"><b>Chưa có quy tắc đối chiếu tự động cho mục tiêu này.</b><div>Tra cứu tiêu chuẩn vẫn hiển thị đầy đủ căn cứ pháp lý. Chỉ khi một đường tiêu chuẩn được cấu hình và xác nhận “Đã kiểm tra” thì hệ thống mới tự động kết luận.</div></div>`;let stats={pass:0,fail:0,review:0,missing:[]};results.forEach(r=>conditionStats(r.condition_tree,stats));let outcome=resultOutcome(results);let missing=[...new Set(stats.missing)].slice(0,6);return `${options.simulation?'<div class="simulation-warning"><b>THỬ GIẢ ĐỊNH — KHÔNG GHI VÀO HỒ SƠ</b><span>Kết quả dưới đây chỉ phục vụ lập kế hoạch và đã được tính trong giao dịch tạm.</span></div>':''}<div class="roadmap-profile"><div><span class="eyebrow">${options.simulation?'HỒ SƠ + DỮ LIỆU GIẢ ĐỊNH':'HỒ SƠ ĐANG PHÂN TÍCH'} · BỘ MÁY ${esc(data.engine_version||window.APP_VERSION||'')}</span><h3>${esc(data.person?.full_name||options.personName||'Hồ sơ đang chọn')}</h3><div class="muted">${data.person?.code?`Mã hồ sơ: ${esc(data.person.code)} · `:''}Năm xét: ${data.year||data.target_year}</div></div><div class="target-focus"><span>Mục tiêu</span><b>${esc(targetName||data.target_code||'Tất cả')}</b></div></div><div class="road-overview outcome-${outcome==='Có thể xem xét'?'pass':outcome==='Chưa đủ điều kiện'?'fail':'review'}"><div class="road-overview-main"><span>KẾT QUẢ TỔNG HỢP</span><h3>${esc(outcome)}</h3><p>Hệ thống rà từng đường tiêu chuẩn độc lập; nếu có một đường hợp lệ đạt thì mục tiêu có thể được đưa vào diện xem xét.</p></div><div class="road-kpis"><div><b>${stats.pass}</b><span>điều kiện đạt</span></div><div><b>${stats.fail}</b><span>điều kiện thiếu</span></div><div><b>${stats.review}</b><span>cần xác minh</span></div></div></div>${missing.length?`<div class="road-tasklist"><div class="tasklist-head"><b>Việc cần xử lý trước</b><span>Tập trung vào các mục chưa đạt hoặc chưa đủ dữ liệu</span></div>${missing.map((x,i)=>`<div class="road-task"><span>${i+1}</span><div>${esc(x)}</div></div>`).join('')}</div>`:'<div class="alert success-soft"><b>Không phát hiện thiếu hụt có thể tính tự động trong các đường tiêu chuẩn đang áp dụng.</b> Vẫn cần hoàn thiện hồ sơ, thẩm quyền và quy trình xét.</div>'}${data.disclaimer?`<div class="alert info">${esc(data.disclaimer)}</div>`:''}<div class="section-title inner"><div><h3>Dữ liệu thành tích trong hồ sơ</h3><div class="muted">Dải năm hiển thị lịch sử để kiểm tra. Không phải mọi năm bên dưới đều được dùng cho mục tiêu hiện tại; từng điều kiện sẽ ghi rõ mốc bắt đầu và các năm thực sự được tính.</div></div></div>${options.simulation?'':renderHistory(data.history||[])}<div class="section-title inner"><div><h3>Chi tiết từng đường tiêu chuẩn</h3><div class="muted">Màu xanh = đạt; đỏ = còn thiếu; vàng = cần cán bộ nghiệp vụ xác minh.</div></div></div>${results.map(r=>`<article class="roadmap-card outcome-${r.outcome==='Có thể xem xét'?'pass':r.outcome==='Chưa đủ điều kiện'?'fail':'review'}"><div class="roadmap-card-head"><div><span class="road-code">${esc(r.rule_code)}</span><h3>${esc(r.rule_name)}</h3><div class="muted">${esc(r.legal_basis||'')}</div></div>${badge(r.outcome)}</div><div class="road-summary"><div><span>Kết luận</span><b>${esc(r.outcome)}</b></div><div><span>Năm xét</span><b>${data.year||data.target_year}</b></div><div><span>Thời điểm sớm nhất*</span><b>${r.earliest_year||'Chưa xác định'}</b></div></div>${r.outcome==='Có thể xem xét'?'<div class="alert success-soft"><b>Đường tiêu chuẩn này đạt theo dữ liệu hiện có.</b> Kết quả không thay thế quyết định khen thưởng.</div>':r.outcome==='Chưa đủ điều kiện'?'<div class="alert danger-soft"><b>Chưa đủ điều kiện theo đường này.</b> Các mục màu đỏ chỉ rõ dữ liệu hoặc thành tích còn thiếu.</div>':'<div class="alert warning"><b>Cần kiểm tra thêm.</b> Có điều kiện không thể tự xác nhận từ dữ liệu hệ thống.</div>'}<div class="condition-tree">${renderConditionTree(r.condition_tree)}</div>${r.legal_refs?`<details class="legal-details"><summary>Căn cứ pháp lý và trích dẫn của đường tiêu chuẩn</summary>${renderLegalRefs(r.legal_refs||[])}</details>`:''}<div class="earliest-note">* Thời điểm sớm nhất chỉ là phép chiếu bảo thủ từ thiếu hụt có thể tính bằng số năm/lần.</div></article>`).join('')}`}

async function loadStandards(){
  let people=await getPeople(), targets=await api('/api/eligibility-targets'), opts=await api('/api/annual/options');
  let currentRoadData=null; let kind='';
  let targetOpts=targets.map(x=>`<option value="${esc(x.target_code)}">${esc(x.name||x.target_code)}</option>`).join('');
  let titleOpts=opts.titles.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('');
  let rewardOpts=opts.rewards.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('');
  $('#content').innerHTML=`<div class="hero-panel integrated-hero"><div><span class="eyebrow">TRA CỨU · ĐỐI CHIẾU · LẬP KẾ HOẠCH</span><h2>Tiêu chuẩn & lộ trình thi đua, khen thưởng</h2><p>Một nơi duy nhất để đọc tiêu chuẩn pháp lý, đối chiếu hồ sơ thực tế và thử giả định tương lai. Kết quả luôn tách rõ <b>đã đạt</b>, <b>còn thiếu</b> và <b>cần xác minh</b>.</p></div><div class="mode-switch"><button class="mode-btn active" data-mode="lookup">Tra cứu tiêu chuẩn</button><button class="mode-btn" data-mode="roadmap">Đối chiếu hồ sơ & lộ trình</button></div></div><div id="legalContext"></div><section id="lookupMode"><div class="lookup-search card"><input id="stdQ" class="input xl search" placeholder="Tìm tên, điều luật, 02/03 năm liên tục, hồ sơ, thủ tục..."><div class="filter-chips"><button class="chip active" data-kind="">Tất cả</button><button class="chip" data-kind="title">Danh hiệu thi đua</button><button class="chip" data-kind="reward">Hình thức khen thưởng</button></div></div><div id="stdRows"></div></section><section id="roadmapMode" hidden><div class="road-process"><div class="road-step active"><span>1</span><div><b>Chọn hồ sơ</b><small>Đối tượng cần rà soát</small></div></div><div class="road-step"><span>2</span><div><b>Chọn mục tiêu</b><small>Danh hiệu/hình thức cần xét</small></div></div><div class="road-step"><span>3</span><div><b>Chọn năm xét</b><small>Khóa mốc thời gian phân tích</small></div></div><div class="road-step"><span>4</span><div><b>Xem thiếu/đủ</b><small>Điều kiện + căn cứ pháp lý</small></div></div></div><div class="card roadmap-control"><div><span class="eyebrow">PHÂN TÍCH HỒ SƠ</span><h3>Chọn đúng mục tiêu trước khi tính lộ trình</h3><p>Không tạo “thang thăng hạng” giả định. Mỗi mục tiêu được kiểm tra theo đúng các đường tiêu chuẩn của chính nó.</p></div><div class="roadmap-form"><label>Hồ sơ<select id="roadPerson">${people.map(p=>`<option value="${p.id}">${esc(p.code)} - ${esc(p.full_name)}</option>`).join('')}</select></label><label>Mục tiêu cần xét<select id="roadTarget"><option value="">— Chọn mục tiêu —</option>${targetOpts}</select></label><label>Năm xét<input id="roadYear" type="number" min="2024" max="2100" value="${new Date().getFullYear()}"></label><button id="analyzeRoad" class="btn primary">Phân tích điều kiện</button></div></div><div id="roadOut" class="road-out"><div class="empty big"><b>Chưa phân tích hồ sơ.</b><div>Chọn hồ sơ, mục tiêu và năm xét để xem chính xác đã đủ hoặc thiếu điều kiện gì.</div></div></div><div id="hypWrap" class="hyp-wrap" hidden><div class="hyp-toggle-head"><div><span class="eyebrow">LẬP KẾ HOẠCH</span><h3>Thử giả định tương lai</h3><p>Thêm một thành tích giả định để xem lộ trình thay đổi thế nào. <b>Không ghi vào hồ sơ thật.</b></p></div><button id="closeHyp" class="btn">Thu gọn</button></div><div class="card hyp-card"><div class="hyp-grid"><label>Năm giả định<input id="hypYear" type="number" min="2024" max="2100" value="${new Date().getFullYear()+1}"></label><label>Xếp loại giả định<select id="hypRating"><option value="">Không giả định xếp loại</option><option>Hoàn thành xuất sắc nhiệm vụ</option><option>Hoàn thành tốt nhiệm vụ</option><option>Hoàn thành nhiệm vụ</option><option>Không hoàn thành nhiệm vụ</option></select></label><label>Danh hiệu giả định<select id="hypTitle"><option value="">Không giả định danh hiệu</option>${titleOpts}</select></label><label>Khen thưởng giả định<select id="hypReward"><option value="">Không giả định khen thưởng</option>${rewardOpts}</select></label><label>Tên sáng kiến/nhiệm vụ<input id="hypIni" placeholder="Chỉ nhập khi muốn thử giả định"></label><label>Phạm vi công nhận<select id="hypScope"><option value="">—</option><option>Cơ sở</option><option>Bộ, ban, ngành, tỉnh</option><option>Toàn quốc</option></select></label></div><button id="runHyp" class="btn primary">Thử giả định và so sánh</button></div><div id="hypOut"></div></div></section>`;
  try{let c=await api('/api/legal-context');$('#legalContext').innerHTML=`<div class="legal-method-inline"><b>Nguyên tắc áp dụng văn bản:</b> ${esc(c.method)}<div class="source-strip">${c.documents.filter(d=>['06/2022/QH15','06/2026/QH16','368/2026/NĐ-CP','25/2026/TT-BNV'].includes(d.code)).map(d=>`<span class="source-pill ${d.status==='Đã kiểm tra'?'ok':'warn'}">${esc(d.code)} · ${esc(d.status)}</span>`).join('')}</div></div>`}catch(e){}
  function setMode(mode){let road=mode==='roadmap';$('#lookupMode').hidden=road;$('#roadmapMode').hidden=!road;$$('.mode-btn').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(road)history.replaceState(null,'',pageHref('/standards?mode=roadmap'));else history.replaceState(null,'',pageHref('/standards'))}
  async function runLookup(){let q=$('#stdQ').value;let rows=await api('/api/standards-catalog?q='+encodeURIComponent(q)+'&kind='+encodeURIComponent(kind));$('#stdRows').innerHTML=rows.length?`<div class="result-count">Tìm thấy <b>${rows.length}</b> / 52 nội dung trong danh mục pháp lý</div>`+rows.map(r=>{let match=targets.find(t=>normText(t.name)===normText(r.name));let current=r.current_law_text||r.law_text||'';return `<article class="standard-card full-standard"><div class="standard-top"><div><div class="standard-type">${r.target_type==='title'?'DANH HIỆU THI ĐUA':'HÌNH THỨC KHEN THƯỞNG'} · STT ${r.stt}</div><h3>${esc(r.name)}</h3><div class="meta-row"><span>Mã: ${esc(r.code)}</span><span>Điều luật chính: Điều ${esc(r.law_article)}</span></div></div><div>${sourceButtons(r.sources)}</div></div><div class="summary-matrix"><div class="matrix-label">Đối tượng xét tặng</div><div class="matrix-value">${esc(r.object_type)}</div><div class="matrix-label">Tiêu chuẩn hiện hành</div><div class="matrix-value"><div class="current-source">${esc(r.law_source)}</div>${r.amendment_note?`<div class="alert warning compact-alert"><b>Phần sửa đổi 2026:</b> ${esc(r.amendment_note)}</div>`:''}<div class="current-law-box"><span>Nội dung dùng để rà soát hiện nay</span>${esc(current)}</div>${r.current_law_text&&r.law_text?`<details><summary>Xem nội dung Luật gốc / phần còn tiếp tục áp dụng</summary><div class="law-text">${esc(r.law_text)}</div></details>`:''}</div><div class="matrix-label">Quy định chi tiết</div><div class="matrix-value">${esc(r.decree_detail||'')}${r.circular_detail?`<div class="circular-box"><b>Thông tư 25/2026/TT-BNV:</b> ${esc(r.circular_detail)}</div>`:''}</div><div class="matrix-label">Hồ sơ, thủ tục xét tặng</div><div class="matrix-value">${esc(r.procedure)}</div><div class="matrix-label">Mức tiền thưởng / hiện vật</div><div class="matrix-value reward-highlight">${esc(r.reward_amount)}</div><div class="matrix-label">Hiệu lực & chuyển tiếp</div><div class="matrix-value">${esc(r.effective_note)}${r.verification_note?`<div class="verification-note">${esc(r.verification_note)}</div>`:''}</div></div><div class="standard-footer"><span>Nguồn pháp lý mặc định: chỉ tài liệu trong Project.</span><div>${sourceButtons(r.sources)}${match?`<button class="btn compact primary road-from-standard" data-target="${esc(match.target_code)}">Đối chiếu hồ sơ theo tiêu chuẩn này →</button>`:''}</div></div></article>`}).join(''):'<div class="empty big"><b>Không tìm thấy nội dung phù hợp.</b><div>Thử tên danh hiệu, số điều hoặc cụm như “02 lần liên tục”.</div></div>';$$('.road-from-standard').forEach(b=>b.onclick=()=>{$('#roadTarget').value=b.dataset.target;setMode('roadmap');$('#roadmapMode').scrollIntoView({behavior:'smooth',block:'start'})})}
  $('#stdQ').oninput=()=>{clearTimeout(window.__stdTimer);window.__stdTimer=setTimeout(runLookup,160)};$$('.chip').forEach(b=>b.onclick=()=>{$$('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');kind=b.dataset.kind;runLookup()});$$('.mode-btn').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
  $('#analyzeRoad').onclick=async()=>{let target=$('#roadTarget').value;if(!target){alert('Hãy chọn mục tiêu cần xét.');return}$('#roadOut').innerHTML='<div class="loading">Đang đọc hồ sơ theo năm và đối chiếu từng nhóm điều kiện…</div>';try{currentRoadData=await api(`/api/eligibility/${$('#roadPerson').value}?year=${$('#roadYear').value}&target_code=${encodeURIComponent(target)}`);let t=targets.find(x=>x.target_code===target);$('#roadOut').innerHTML=renderRoadmapAnalysis(currentRoadData,t?.name||target)+`<div class="road-actions"><button id="openHyp" class="btn">◇ Thử giả định tương lai</button></div>`;$('#openHyp').onclick=()=>{$('#hypWrap').hidden=false;$('#hypYear').value=Math.max(Number($('#roadYear').value)+1,new Date().getFullYear()+1);$('#hypWrap').scrollIntoView({behavior:'smooth',block:'start'})}}catch(e){$('#roadOut').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}};
  $('#closeHyp').onclick=()=>{$('#hypWrap').hidden=true;$('#hypOut').innerHTML=''};
  $('#runHyp').onclick=async()=>{let target=$('#roadTarget').value;if(!target){alert('Cần phân tích một mục tiêu trước.');return}let future={year:Number($('#hypYear').value)};if($('#hypRating').value)future.rating=$('#hypRating').value;if($('#hypTitle').value)future.title=$('#hypTitle').value;if($('#hypReward').value)future.reward=$('#hypReward').value;if($('#hypIni').value.trim())future.initiative={name:$('#hypIni').value.trim(),scope:$('#hypScope').value||null};if(Object.keys(future).length===1){alert('Hãy chọn ít nhất một thành tích giả định.');return}let f=new FormData();f.append('base_year',$('#roadYear').value);f.append('target_code',target);f.append('scenario_json',JSON.stringify({name:'Giả định lộ trình',future}));$('#hypOut').innerHTML='<div class="loading">Đang tính thử mà không ghi vào hồ sơ…</div>';try{let d=await api('/api/simulate/'+$('#roadPerson').value,{method:'POST',body:f});let t=targets.find(x=>x.target_code===target);let before=resultOutcome(currentRoadData?.results||[]), after=resultOutcome(d.result.results||[]);let simData={...d.result,person:currentRoadData?.person,year:d.result.target_year,disclaimer:d.result.note,history:[]};$('#hypOut').innerHTML=`<div class="compare-strip"><div><span>Hồ sơ thực tế (${currentRoadData?.year})</span>${badge(before)}</div><div class="compare-arrow">→</div><div><span>Sau giả định (${d.result.target_year})</span>${badge(after)}</div></div>`+renderRoadmapAnalysis(simData,t?.name||target,{simulation:true,personName:currentRoadData?.person?.full_name})}catch(e){$('#hypOut').innerHTML=`<div class="alert danger">${esc(e.message)}</div>`}};
  await runLookup();let params=new URLSearchParams(location.search);setMode(params.get('mode')==='roadmap'?'roadmap':'lookup');if(params.get('hyp')==='1'){$('#hypWrap').hidden=false}
}
async function loadEligibility(){location.replace('standards.html?mode=roadmap')}
async function loadRoadmap(){location.replace('standards.html?mode=roadmap')}

async function loadLegal(){let rows=await api('/api/legal-documents');let today=new Date().toISOString().slice(0,10);let current=rows.filter(x=>!x.expiry_date||x.expiry_date>=today), historical=rows.filter(x=>x.expiry_date&&x.expiry_date<today);let core=['06/2022/QH15','06/2026/QH16','368/2026/NĐ-CP','25/2026/TT-BNV'];function docTable(list){return `<div class="table-wrap"><table><thead><tr><th>Số/ký hiệu</th><th>Tên văn bản</th><th>Cơ quan</th><th>Hiệu lực</th><th>Trạng thái</th></tr></thead><tbody>${list.map(x=>`<tr class="${core.includes(x.code)?'core-doc':''}"><td><b>${esc(x.code)}</b>${core.includes(x.code)?'<div class="core-label">KHUNG HIỆN HÀNH</div>':''}</td><td>${esc(x.title)}${x.notes?`<div class="muted">${esc(x.notes)}</div>`:''}</td><td>${esc(x.issuer)}</td><td>${esc(x.effective_date||'—')}${x.expiry_date?`<div class="muted">Hết: ${esc(x.expiry_date)}</div>`:''}</td><td>${badge(x.verification_status)}${x.source_url?`<br><a target="_blank" href="${x.source_url}">Xem nguồn ↗</a>`:''}</td></tr>`).join('')}</tbody></table></div>`}$('#content').innerHTML=`<div class="legal-page-hero"><div><span class="eyebrow">NGUỒN PHÁP LÝ CỦA HỆ THỐNG</span><h2>Phân biệt văn bản đang áp dụng và nguồn lịch sử</h2><p>Khung hiện hành từ 01/10/2026 được đọc theo phương pháp hợp nhất: Luật gốc + phần sửa đổi + nghị định + thông tư hướng dẫn tương ứng.</p></div><div class="source-strip">${core.map(x=>`<span class="source-pill ok">${x}</span>`).join('')}</div></div><div class="section-title"><div><h2>Đang áp dụng / còn hiệu lực trong dữ liệu nguồn</h2><div class="muted">Văn bản lõi được đánh dấu để dễ kiểm soát căn cứ.</div></div>${APP_USER.role==='admin'?'<button id="addDoc" class="btn primary">+ Thêm văn bản</button>':''}</div>${docTable(current)}${historical.length?`<details class="history-docs"><summary>Nguồn lịch sử / đã hết hiệu lực (${historical.length})</summary>${docTable(historical)}</details>`:''}<div class="alert info"><b>Lưu ý nguồn:</b> Các tài liệu bên ngoài (nếu có) chỉ được dùng để tham khảo thiết kế/giao diện và được ghi riêng trong tài liệu nguồn tham khảo; không dùng làm căn cứ pháp lý của bộ quy tắc.</div>`;if($('#addDoc'))$('#addDoc').onclick=()=>modal('Thêm văn bản','<div class="alert info">Bản HTML tĩnh không thêm tệp văn bản pháp lý trực tiếp trên GitHub. Danh mục pháp lý đi kèm phiên bản được giữ ở chế độ chỉ đọc để tránh sửa nhầm căn cứ.</div>')}

async function loadReports(){let p=await getPeople();$('#content').innerHTML=`<div class="card"><h2>Xuất hồ sơ thành tích</h2><div class="toolbar"><select id="rp">${p.map(x=>`<option value="${x.id}">${esc(x.code)} - ${esc(x.full_name)}</option>`).join('')}</select><a id="rx" class="btn" href="#">Excel</a><a id="rw" class="btn" href="#">Word hành chính</a><a id="rwp" class="btn" href="#">Word mẫu Đảng*</a><a id="rp2" class="btn" href="#">PDF</a></div><div class="alert warning">* Mẫu văn bản Đảng được gắn cảnh báo “Cần cán bộ nghiệp vụ kiểm tra” vì trong nguồn dự án hiện chưa có tệp Hướng dẫn 05-HD/VPTW để xác minh đầy đủ thể thức.</div><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h3>Báo cáo theo năm</h3><div class="toolbar"><input id="reportYear" type="number" value="${new Date().getFullYear()}"><a id="annualX" class="btn" href="#">Xuất Excel theo năm</a></div></div>`;function links(){let id=$('#rp').value;$('#rx').href=`/api/reports/personnel/${id}.xlsx`;$('#rw').href=`/api/reports/personnel/${id}.docx`;$('#rwp').href=`/api/reports/personnel/${id}.docx?party_style=true`;$('#rp2').href=`/api/reports/personnel/${id}.pdf`}$('#rp').onchange=links;function annualLink(){$('#annualX').href=`/api/reports/annual.xlsx?year=${$('#reportYear').value}`}$('#reportYear').onchange=annualLink;links();annualLink()}
async function loadAdmin(){if(APP_USER.role!=='admin'){$('#content').innerHTML='<div class="alert danger">Chỉ Quản trị viên được truy cập phân hệ này.</div>';return}let us=await api('/api/admin/users');$('#content').innerHTML=`<div class="section-title"><h2>Tài khoản và phân quyền</h2><div class="toolbar"><button id="newUser" class="btn primary">+ Tạo tài khoản</button><a class="btn" href="/api/admin/backup">Sao lưu toàn bộ</a></div></div><div class="table-wrap"><table><thead><tr><th>Tên đăng nhập</th><th>Họ tên</th><th>Vai trò</th><th>Đơn vị</th><th>Trạng thái</th></tr></thead><tbody>${us.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(u.full_name)}</td><td>${esc(u.role)}</td><td>${esc(u.department_id||'Toàn hệ thống')}</td><td>${u.is_active?badge('Đã kiểm tra'):badge('Hết hiệu lực')}</td></tr>`).join('')}</tbody></table></div><div class="section-title"><h2>An toàn dữ liệu</h2></div><div class="card"><p>✓ Mật khẩu băm scrypt.</p><p>✓ Khóa tạm thời sau 5 lần đăng nhập sai.</p><p>✓ Phiên đăng nhập cookie HttpOnly.</p><p>✓ Phân quyền phía máy chủ theo vai trò và đơn vị.</p><p>✓ Tệp minh chứng ở vùng riêng tư, đường dẫn tạm thời có chữ ký.</p><p>✓ Nhật ký đăng nhập, thêm, sửa, chốt, xuất và mô phỏng.</p></div><div class="section-title"><h2>Nhật ký gần đây</h2><button id="loadAudit" class="btn">Tải nhật ký</button></div><div id="auditBox"></div>`;$('#newUser').onclick=async()=>{let ds=await getDepts();let m=modal('Tạo tài khoản',`<form id="uForm" class="form-grid"><label>Tên đăng nhập<input name="username" required></label><label>Họ tên<input name="full_name" required></label><label>Vai trò<select name="role"><option value="officer">Cán bộ nghiệp vụ</option><option value="viewer">Người xem</option><option value="admin">Quản trị viên</option></select></label><label>Đơn vị<select name="department_id"><option value="">Toàn hệ thống</option>${ds.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label><label class="full">Mật khẩu tạm<input type="password" name="password" minlength="10" required></label><div class="full"><button class="btn primary">Tạo tài khoản</button></div></form>`);$('#uForm',m).onsubmit=async e=>{e.preventDefault();let fd=new FormData(e.target);if(!fd.get('department_id'))fd.delete('department_id');try{await api('/api/admin/users',{method:'POST',body:fd});m.classList.remove('show');loadAdmin()}catch(err){alert(err.message)}}};$('#loadAudit').onclick=async()=>{let logs=await api('/api/admin/audit-logs?limit=50');$('#auditBox').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Người dùng</th><th>Thao tác</th><th>Đối tượng</th><th>Chi tiết</th></tr></thead><tbody>${logs.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.user_id)}</td><td>${esc(x.action)}</td><td>${esc(x.entity_type)} ${esc(x.entity_id||'')}</td><td>${esc(JSON.stringify(x.detail||{}))}</td></tr>`).join('')}</tbody></table></div>`}}
async function loadReportsStatic(){
  const people=await getPeople();
  $('#content').innerHTML=`<div class="hero-panel"><div><span class="eyebrow">BẢN HTML TĨNH</span><h2>Báo cáo và xuất dữ liệu</h2><p>Dữ liệu nằm trên trình duyệt hiện tại. CSV có thể mở trực tiếp bằng Excel; bản in có thể chọn “Save as PDF” trong hộp thoại in của trình duyệt.</p></div></div><div class="card"><h3>Hồ sơ cá nhân</h3><div class="toolbar"><select id="rp">${people.map(x=>`<option value="${x.id}">${esc(x.code)} - ${esc(x.full_name)}</option>`).join('')}</select><button id="csvPerson" class="btn primary">Xuất CSV (mở bằng Excel)</button><button id="printPerson" class="btn">In / Lưu PDF</button></div>${people.length?'':'<div class="empty">Chưa có hồ sơ cá nhân.</div>'}<hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h3>Báo cáo theo năm</h3><div class="toolbar"><input id="reportYear" type="number" value="${new Date().getFullYear()}"><button id="csvAnnual" class="btn primary">Xuất CSV theo năm</button></div></div><div class="alert info"><b>Không cần Python.</b> Bản tĩnh dùng các định dạng mà trình duyệt tạo trực tiếp. Khi cần Word/PDF theo mẫu hành chính hoàn chỉnh, có thể bổ sung ở phiên bản sau bằng thư viện JavaScript đóng gói trong website.</div>`;
  $('#csvPerson')?.addEventListener('click',()=>protectedFile(`/api/reports/personnel/${$('#rp').value}.xlsx`));
  $('#printPerson')?.addEventListener('click',()=>protectedFile(`/api/reports/personnel/${$('#rp').value}.pdf`,true));
  $('#csvAnnual')?.addEventListener('click',()=>protectedFile(`/api/reports/annual.xlsx?year=${$('#reportYear').value}`));
}
async function loadAdminStatic(){
  const db=window.TDKT_LOCAL.loadDb();
  $('#content').innerHTML=`<div class="hero-panel"><div><span class="eyebrow">QUẢN LÝ DỮ LIỆU CỤC BỘ</span><h2>Sao lưu, chuyển máy và khôi phục</h2><p>Toàn bộ hồ sơ bạn nhập được lưu trong trình duyệt hiện tại. Hãy sao lưu định kỳ để tránh mất dữ liệu khi xóa bộ nhớ trình duyệt hoặc đổi máy.</p></div></div><div class="grid" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div class="card"><h3>① Sao lưu</h3><p class="muted">Tải toàn bộ dữ liệu thành một tệp JSON.</p><button id="backupLocal" class="btn primary">Tải tệp sao lưu JSON</button></div><div class="card"><h3>② Khôi phục / chuyển máy</h3><p class="muted">Chọn tệp JSON đã sao lưu từ máy khác hoặc từ lần trước.</p><input id="restoreFile" type="file" accept=".json,application/json"><button id="restoreLocal" class="btn" style="margin-top:10px">Khôi phục dữ liệu</button></div><div class="card"><h3>③ Xóa dữ liệu trên máy này</h3><p class="muted">Chỉ xóa dữ liệu trong trình duyệt hiện tại, không ảnh hưởng các máy khác.</p><button id="resetLocal" class="btn danger">Xóa dữ liệu cục bộ</button></div></div><div class="section-title"><h2>Thông tin lưu trữ</h2></div><div class="card"><p><b>Phiên bản:</b> ${esc(window.TDKT_LOCAL.VERSION)}</p><p><b>Hồ sơ cá nhân:</b> ${db.personnel.length}</p><p><b>Bản ghi theo năm:</b> ${db.performances.length}</p><p><b>Danh hiệu:</b> ${db.titles.filter(x=>x.is_active!==false).length}</p><p><b>Khen thưởng:</b> ${db.rewards.filter(x=>x.is_active!==false).length}</p><p><b>Sáng kiến/nhiệm vụ:</b> ${db.initiatives.filter(x=>x.is_active!==false).length}</p></div><div class="alert warning"><b>Giới hạn của GitHub Pages:</b> website là tĩnh nên mỗi trình duyệt có một bộ dữ liệu riêng. Không có đồng bộ tự động giữa nhiều người. Tài khoản/mật khẩu trong bản này chỉ là tiện ích cục bộ, không phải cơ chế bảo mật máy chủ.</div>`;
  $('#backupLocal').onclick=()=>window.TDKT_LOCAL.exportBackup();
  $('#restoreLocal').onclick=async()=>{const f=$('#restoreFile').files[0];if(!f){alert('Hãy chọn tệp sao lưu .json');return}if(!confirm('Khôi phục sẽ thay toàn bộ dữ liệu hiện có trên trình duyệt này. Tiếp tục?'))return;try{await window.TDKT_LOCAL.importBackup(f);alert('Đã khôi phục dữ liệu. Trang sẽ tải lại.');location.reload()}catch(e){alert(e.message)}};
  $('#resetLocal').onclick=()=>{if(confirm('Xóa toàn bộ dữ liệu TĐKT trên trình duyệt này? Hành động này không thể hoàn tác nếu chưa có tệp sao lưu.')){window.TDKT_LOCAL.resetData();alert('Đã xóa dữ liệu cục bộ.');location.reload()}};
}
function enhanceAnnualStatic(){
  const tab=$('[data-annual-tab="import"]'); if(tab) tab.textContent='③ Sao lưu / chuyển máy';
  const sec=$('#annualTabImport'); if(!sec)return;
  sec.innerHTML=`<div class="card import-card"><div><span class="eyebrow">DỮ LIỆU CỤC BỘ</span><h3>Sao lưu hoặc chuyển dữ liệu sang máy khác</h3><p class="muted">GitHub Pages không có cơ sở dữ liệu dùng chung. Dùng tệp JSON để chuyển toàn bộ hồ sơ giữa các trình duyệt/máy.</p></div><div class="import-box"><div class="toolbar"><button id="annualBackup" class="btn primary">Tải sao lưu JSON</button><a class="btn" href="admin.html">Mở Quản trị để khôi phục</a><a class="btn" href="mau_nhap_du_lieu.xlsx">Tải mẫu Excel tham khảo</a></div></div><div class="alert info">Mẫu Excel vẫn được giữ để chuẩn bị dữ liệu. Bản HTML tĩnh hiện ưu tiên nhập trực tiếp trên giao diện và sao lưu/khôi phục bằng JSON để không cần Python.</div></div>`;
  $('#annualBackup')?.addEventListener('click',()=>window.TDKT_LOCAL.exportBackup());
}
const loaders={dashboard:loadDashboard,personnel:loadPersonnel,annual:loadAnnual,standards:loadStandards,eligibility:loadEligibility,roadmap:loadRoadmap,legal:loadLegal,reports:loadReportsStatic,admin:loadAdminStatic};
async function bootstrapStatic(){
  rewriteLinks(document);
  const me=await api('/api/me');
  window.APP_USER=me;
  if(me.must_change_password){location='change-password.html';return}
  const name=$('#userName'),role=$('#userRole');if(name)name.textContent=me.full_name||me.username;if(role)role.textContent=me.role==='admin'?'Quản trị viên':(me.role==='officer'?'Cán bộ nghiệp vụ':'Người xem');
  $('#logoutBtn')?.addEventListener('click',async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch{}setToken('');location='login.html'});
  await loaders[APP_PAGE]?.();if(APP_PAGE==='annual')enhanceAnnualStatic();rewriteLinks(document);
}
bootstrapStatic().catch(e=>{if(e.message==='unauthorized'||e.message==='must-change-password')return;$('#content').innerHTML=`<div class="alert danger"><b>Không tải được dữ liệu cục bộ.</b><br>${esc(e.message)}<br><small>Hãy thử tải lại trang hoặc khôi phục tệp sao lưu JSON.</small></div>`});
